CREATE TYPE "message_role" AS ENUM ('system', 'user', 'assistant');
CREATE TYPE "generation_status" AS ENUM ('pending', 'streaming', 'completed', 'failed', 'cancelled');
CREATE TABLE "users" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "name" text NOT NULL DEFAULT 'Local user', "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "providers" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "name" text NOT NULL, "base_url" text NOT NULL, "encrypted_api_key" text NOT NULL, "custom_headers" text, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "providers_user_name_idx" ON "providers" ("user_id", "name");
CREATE TABLE "models" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "provider_id" uuid NOT NULL REFERENCES "providers"("id") ON DELETE CASCADE, "name" text NOT NULL, "display_name" text NOT NULL, "input_price_per_million" numeric(12,6) NOT NULL DEFAULT 0, "output_price_per_million" numeric(12,6) NOT NULL DEFAULT 0, "context_window" integer, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "models_provider_name_idx" ON "models" ("provider_id", "name");
CREATE TABLE "conversations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "title" text NOT NULL DEFAULT 'New conversation', "model_id" uuid REFERENCES "models"("id") ON DELETE SET NULL, "system_prompt" text, "temperature" numeric(3,2) NOT NULL DEFAULT .7, "top_p" numeric(3,2) NOT NULL DEFAULT 1, "max_output_tokens" integer NOT NULL DEFAULT 2048, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX "conversations_user_updated_idx" ON "conversations" ("user_id", "updated_at");
CREATE TABLE "messages" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "conversation_id" uuid NOT NULL REFERENCES "conversations"("id") ON DELETE CASCADE, "role" "message_role" NOT NULL, "content" text NOT NULL, "parent_id" uuid, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX "messages_conversation_created_idx" ON "messages" ("conversation_id", "created_at");
CREATE TABLE "generations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "conversation_id" uuid NOT NULL REFERENCES "conversations"("id") ON DELETE CASCADE, "message_id" uuid REFERENCES "messages"("id") ON DELETE SET NULL, "model_id" uuid NOT NULL REFERENCES "models"("id") ON DELETE RESTRICT, "status" "generation_status" NOT NULL DEFAULT 'pending', "error_code" text, "started_at" timestamptz NOT NULL DEFAULT now(), "completed_at" timestamptz);
CREATE INDEX "generations_conversation_idx" ON "generations" ("conversation_id");
CREATE TABLE "usage_records" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "generation_id" uuid NOT NULL UNIQUE REFERENCES "generations"("id") ON DELETE CASCADE, "provider_name" text NOT NULL, "model_name" text NOT NULL, "input_tokens" integer, "output_tokens" integer, "total_tokens" integer, "duration_ms" integer NOT NULL, "ttft_ms" integer, "tokens_per_second" numeric(10,2), "estimated_input_cost" numeric(12,8), "estimated_output_cost" numeric(12,8), "estimated_total_cost" numeric(12,8), "created_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX "usage_created_idx" ON "usage_records" ("created_at");
CREATE INDEX "usage_model_idx" ON "usage_records" ("model_name");
